steps.code:
# /srv/openbao/config/bao.hcl
ui            = true
disable_mlock = true
api_addr      = "https://bao-1.example.internal:8200"
cluster_addr  = "https://bao-1.example.internal:8201"
listener "tcp" {
  address       = "0.0.0.0:8200"
  tls_cert_file = "/openbao/tls/tls.crt"
  tls_key_file  = "/openbao/tls/tls.key"
}
storage "raft" {
  path    = "/openbao/data"
  node_id = "bao-1"
  retry_join {
    leader_api_addr     = "https://bao-2.example.internal:8200"
    leader_ca_cert_file = "/openbao/tls/tls.crt"
  }
}

# /etc/openbao/agent.hcl  (run: bao agent -config=/etc/openbao/agent.hcl)
vault {
  address = "https://bao-1.example.internal:8200"
  ca_cert = "/etc/openbao/ca.crt"
}
auto_auth {
  method "approle" {
    config = {
      role_id_file_path   = "/etc/openbao/role_id"
      secret_id_file_path = "/etc/openbao/secret_id"
    }
  }
}
template {
  contents    = "{{ with secret \"secret/data/myapp/config\" }}DB_PASS={{ .Data.data.db_pass }}{{ end }}"
  destination = "/run/myapp/env"
  perms       = "0640"
}
